<template><el-card><h1>单词工作台</h1><el-input v-model="text" type="textarea" :rows="8" placeholder="apple 苹果&#10;banana 香蕉"/><el-button type="primary" @click="parse">解析</el-button><el-button @click="generate">生成文档</el-button><el-row :gutter="16"><el-col :span="12"><h3>原版预览</h3><p v-for="i in items" :key="i.word"><b>{{ i.word }}</b> {{ i.meaning }}</p></el-col><el-col :span="12"><h3>默写版预览</h3><p v-for="i in items" :key="i.word">__________ {{ i.meaning }}</p></el-col></el-row></el-card></template>
<script setup>import{ref}from'vue';import{ElMessage}from'element-plus';import{parseText,createDocument}from'@/api/client';const text=ref('apple 苹果\nbanana 香蕉\nbeautiful 美丽的');const items=ref([]);async function parse(){const{data}=await parseText(text.value);items.value=data.data.items}async function generate(){const{data}=await createDocument(text.value);ElMessage.success(`已生成文档，单词数：${data.data.word_count}`)}</script>
